#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
int main() {
    int n; cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    sort(a.begin(), a.end());
    int q; cin >> q;
    while (q--) {
        int k; cin >> k;
        cout << a[k-1] << "\n";
    }
    return 0;
}

