import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextInt();
        Arrays.sort(a);
        int q = sc.nextInt();
        while (q-- > 0) {
            int k = sc.nextInt();
            System.out.println(a[k-1]);
        }
    }
}
